// Cleric Protection System Demo Request Parser
const request = $input.first().json;

// Demo scenario setup
const demoScenario = {
  character_request: request.character_request || "I want to protect my party members and keep them alive through dangerous situations",
  character_id: request.character_id || 'cleric_thalia_001',
  character_class: 'cleric',
  character_level: request.character_level || 8,
  party_composition: [
    { name: 'Thorin', class: 'fighter', role: 'tank' },
    { name: 'Elena', class: 'wizard', role: 'damage_dealer' },
    { name: 'Rogar', class: 'rogue', role: 'scout' },
    { name: 'Thalia', class: 'cleric', role: 'healer_support' }
  ],
  current_situation: request.current_situation || 'Exploring ancient dungeon with frequent combat encounters',
  play_style: 'supportive_and_vigilant',
  preferences: {
    protection_priority: 'high',
    healing_style: 'proactive',
    resource_management: 'conservative',
    communication: 'clear_and_reassuring'
  }
};

return [{
  json: {
    demo_scenario: demoScenario,
    timestamp: new Date().toISOString(),
    demo_mode: 'cleric_protection_system'
  }
}];

// Create demo request for Code Fabric Orchestrator
const demo = $input.first().json;

const orchestratorRequest = {
  character_request: demo.demo_scenario.character_request,
  character_id: demo.demo_scenario.character_id,
  character_class: demo.demo_scenario.character_class,
  character_level: demo.demo_scenario.character_level,
  party_composition: demo.demo_scenario.party_composition,
  current_situation: demo.demo_scenario.current_situation,
  play_style: demo.demo_scenario.play_style,
  preferences: demo.demo_scenario.preferences,
  processing_mode: 'comprehensive',
  include_learning: true,
  include_pattern_matching: true,
  generate_complete_solution: true,
  provide_explanations: true,
  enable_feedback_loop: true
};

return [{
  json: {
    ...demo,
    orchestrator_request: orchestratorRequest
  }
}];

// Process orchestrator response and create demo-specific enhancements
const response = $input.first().json;
const originalDemo = items.find(item => item.json.orchestrator_request)?.json;

const demoEnhancements = {
  character_persona: {
    name: 'Thalia',
    title: 'Guardian Angel of the Party',
    personality: 'nurturing, vigilant, and deeply devoted to protecting her allies',
    motivation: 'believes every party member deserves a chance to shine and fulfill their destiny',
    protection_philosophy: 'prevention is better than cure, but be ready for both'
  },
  demo_scenarios: [
    {
      scenario_name: 'Ambush Protection',
      situation: 'Party ambushed by goblins in narrow corridor',
      trigger: 'Thorin (fighter) health drops below 40%',
      automation_response: [
        'Cast Shield of Faith on Thorin (+2 AC bonus)',
        'Move to protect position between Thorin and enemies',
        'Prepare Cure Wounds for immediate healing if needed',
        'Alert party of tactical positioning needs'
      ],
      expected_outcome: 'Thorin survives initial attack, party maintains defensive formation'
    },
    {
      scenario_name: 'Area Effect Protection',
      situation: 'Enemy wizard prepares Fireball spell',
      trigger: 'Enemy spellcaster detected preparing area effect spell',
      automation_response: [
        'Cast Protection from Energy on most vulnerable party member',
        'Position self to absorb damage if possible',
        'Prepare mass healing for multiple injuries',
        'Coordinate with party to spread out formation'
      ],
      expected_outcome: 'Party damage minimized, quick recovery from area effect'
    },
    {
      scenario_name: 'Proactive Healing',
      situation: 'Party preparing for known boss battle',
      trigger: 'Rest period before dangerous encounter',
      automation_response: [
        'Cast Bless on entire party (+1 to attacks and saves)',
        'Prepare higher-level healing spells (Prayer of Healing)',
        'Distribute healing potions to party members',
        'Establish emergency signal for combat healing'
      ],
      expected_outcome: 'Party enters battle buffed and prepared for healing'
    }
  ],
  character_voice_responses: [
    { trigger: 'party_member_injured', response: "Stay with me! I won't let you fall!" },
    { trigger: 'pre_combat_preparation', response: "Divine light guide and protect us in the coming battle." },
    { trigger: 'successful_protection', response: "The divine shield holds! We are safe for now." },
    { trigger: 'healing_needed', response: "Let the holy light restore your strength." },
    { trigger: 'critical_situation', response: "Stand together! My faith will shield us all!" }
  ],
  learning_examples: [
    {
      situation: 'Failed to protect wizard from surprise attack',
      learning: 'Improve threat detection and positioning for vulnerable party members',
      adaptation: 'Prioritize protection of spellcasters in surprise scenarios'
    },
    {
      situation: 'Used too many high-level spells on minor threats',
      learning: 'Better threat assessment and resource allocation',
      adaptation: 'Scale healing/protection based on actual threat level'
    },
    {
      situation: 'Successfully prevented TPK (Total Party Kill) through quick action',
      learning: 'Proactive positioning and preparedness are critical',
      adaptation: 'Maintain defensive positioning during uncertain situations'
    }
  ]
};

return [{
  json: {
    orchestrator_response: response,
    demo_enhancements: demoEnhancements,
    demo_scenario: originalDemo.demo_scenario,
    processing_summary: {
      total_processing_time: response.processing_summary?.total_processing_time || 0,
      phases_completed: response.processing_summary?.completed_phases || 0,

  character_intent_understood: response.character_understanding?.interpreted_intent || 'Intent analysis failed',
    business_goal_identified: response.character_understanding?.business_goal || 'Goal identification failed',
    automation_type_recommended: response.character_understanding?.automation_type || 'general'
    }
  }
}];

// Create comprehensive demo showcase
const response = $input.first().json;

const demoShowcase = {
  demo_title: 'Thalia the Cleric - Divine Protection System',
  demo_overview: {
    character_profile: response.demo_enhancements.character_persona,
    primary_goal: response.demo_scenario.character_request,
    system_approach: 'Proactive protection with reactive healing capabilities',
    core_philosophy: response.demo_enhancements.character_persona.protection_philosophy
  },
  intelligence_analysis: {
    semantic_understanding: {
      what_thalia_said: response.demo_scenario.character_request,
      what_she_means: response.orchestrator_response.character_understanding?.interpreted_intent,
      business_goal: response.orchestrator_response.character_understanding?.business_goal,
      automation_approach: response.orchestrator_response.character_understanding?.automation_type
    },
    pattern_recognition: {
      patterns_identified: response.orchestrator_response.solution_components?.pattern_matches?.pattern_analysis?.patterns_identified || 0,
      success_probability: response.orchestrator_response.solution_components?.pattern_matches?.implementation_readiness?.overall_readiness || 'unknown',
      learning_opportunities: response.orchestrator_response.recommendations?.learning_opportunities || []
    },
    business_strategy: {
      problem_statement: response.orchestrator_response.solution_components?.business_strategy?.strategic_analysis?.problem_statement,
      business_impact: response.orchestrator_response.solution_components?.business_strategy?.strategic_analysis?.business_impact,
      implementation_complexity: response.orchestrator_response.solution_components?.business_strategy?.implementation_readiness?.complexity_score
    }
  },
  practical_demonstrations: response.demo_enhancements.demo_scenarios,
  character_experience: {
    interaction_style: 'Voice commands with natural language understanding',
    feedback_system: 'Divine-themed notifications and status updates',
    customization_options: [
      'Protection priority settings (party member hierarchy)',
      'Healing aggressiveness (conservative vs proactive)',
      'Resource management (spell slot conservation)',
      'Communication preferences (alerts and updates)'
    ],
    voice_commands: response.demo_enhancements.character_voice_responses
  },
  learning_and_adaptation: {
    adaptive_capabilities: [
      'Learns from each combat encounter',
      'Adapts protection strategies based on party composition',
      'Improves threat assessment over time',
      'Optimizes resource usage based on success patterns'
    ],
    learning_examples: response.demo_enhancements.learning_examples,
    improvement_mechanisms: [
      'Analyzes combat effectiveness after each encounter',
      'Tracks which protection strategies work best',
      'Adjusts priority based on party member performance',
      'Learns enemy attack patterns for better anticipation'
    ]
  },
  technical_highlights: {
    architecture_components: response.orchestrator_response.processing_summary?.total_phases || 0,
    processing_phases: [
      'Semantic Understanding - Analyzes character intent',
      'Pattern Recognition - Identifies successful protection strategies',
      'Business Logic - Translates goals into technical requirements',
      'Solution Architecture - Generates complete automation system'
    ],
    ai_integration: 'DeepSeek API for advanced reasoning and pattern analysis',
    integration_points: [
      'Party health monitoring',
      'Combat threat detection',
      'Resource management (spell slots)',
      'Position tracking and movement'
    ]
  },
  expected_outcomes: {
    immediate_benefits: [
      'Faster response to party member injuries',
      'Proactive protection before damage occurs',
      'Optimal use of healing resources',
      'Improved party survivability'
    ],
    long_term_benefits: [
      'Deeper understanding of party protection needs',
      'Improved combat tactics and positioning',
      'Better resource management over time',
      'Enhanced party coordination and trust'
    ],
    success_metrics: [
      'Reduced party member injuries by 40%',
      'Faster healing response times (under 2 seconds)',
      '90% successful protection of critical party members',
      'Improved resource efficiency (25% fewer wasted spells)'
    ]
  },
  next_steps: [
    'Review and customize protection priorities',
    'Test system in controlled combat scenarios',
    'Fine-tune based on party feedback',
    'Deploy for regular use with monitoring'
  ],
  demo_metadata: {
    processing_time: response.orchestrator_response.processing_summary?.total_processing_time || 0,
    confidence_score: response.orchestrator_response.quality_metrics?.confidence_score || 0,
    completeness_score: response.orchestrator_response.quality_metrics?.completeness_score || 0,
    estimated_accuracy: response.orchestrator_response.quality_metrics?.accuracy_estimate || 0
  }
};

return [{
  json: demoShowcase
}];

// Generate character-friendly final response
const showcase = $input.first().json;

const characterFriendlyResponse = {
  greeting: '🙏 Welcome, Thalia! Your Divine Protection System is ready!',
  what_i_understand: {
    your_request: showcase.demo_overview.primary_goal,
    your_character: `${showcase.demo_overview.character_profile.name}, the ${showcase.demo_overview.character_profile.title}`,
    your_approach: showcase.demo_overview.system_approach
  },
  what_system_does: {
    main_purpose: 'Automatically protects your party members and keeps them safe',
    how_it_works: 'Monitors danger, predicts threats, and acts before damage occurs',
    your_control: 'You can customize everything and override when needed'
  },
  example_scenarios: showcase.practical_demonstrations.map(scenario => ({
    when_this_happens: scenario.situation,
    what_system_does: scenario.automation_response.slice(0, 2).join(', '),
    result: scenario.expected_outcome
  })),
  your_special_features: {
    divine_intelligence: 'Learns from each battle to protect better next time',
    party_awareness: 'Knows your party members and their roles',
    proactive_healing: 'Heals before injuries become critical',
    resource_wisdom: 'Uses spells efficiently to always have healing ready'
  },
  how_to_use_it: {
    voice_commands: [
      '"Protect Thorin" - Focus protection on specific member',
      '"Heal party" - Emergency healing for everyone',
      '"Check status" - See how everyone is doing',
      '"Adjust settings" - Change protection priorities'
    ],
    what_you_see: [
      'Divine light effects when protection activates',
      'Status messages showing party health',
      'Notifications when healing is needed',
      'Battle results and learning insights'
    ]
  },
  what_to_expect: {
    first_session: 'The system will learn your style and adapt to your party',
    learning_process: 'Each battle makes the protection smarter',
    your_role: 'You remain the leader - system just handles the details',
    party_benefits: 'Everyone stays safer and can focus on their roles'
  },
  getting_started: [
    'Review protection priorities for your party',
    'Test the system in a safe combat scenario',
    'Customize alerts and notifications to your preference',
    'Use it in real battles and provide feedback'
  ],
  reassurance: {
    your_authority: 'You always have final say over the automation',
    safety_first: 'System designed to prevent harm and save lives',
    learning_together: 'Grows smarter with your guidance and experience',
    divine_blessing: 'Your faith and wisdom guide the system's actions'
  },
  support: {
    help_available: 'Always ask questions if anything is unclear',
    feedback_welcome: 'Your experience helps improve the system',
    adjustments_possible: 'We can change settings based on your preferences',
    growth_potential: 'System evolves with you and your party'
  },
  closing: 'May your divine light always guide and protect your party! 🙏✨'
};

return [{
  json: {
    character_friendly_response: characterFriendlyResponse,
    technical_details: showcase,
    session_summary: {
      character_name: showcase.demo_overview.character_profile.name,
      system_name: showcase.demo_overview.character_persona.title,
      confidence_level: showcase.demo_metadata.confidence_score,
      ready_for_use: showcase.demo_metadata.completeness_score > 80,
      processing_time: showcase.demo_metadata.processing_time
    }
  }
}];
